/* From Uiverse.io by boryanakrasteva - Tags: loader */
@-webkit-keyframes follow-the-leader {
  0% {
    -webkit-transform: rotate(0deg) translateY(-200%);
    transform: rotate(0deg) translateY(-200%);
  }

  60%,
  100% {
    -webkit-transform: rotate(360deg) translateY(-200%);
    transform: rotate(360deg) translateY(-200%);
  }
}

@keyframes follow-the-leader {
  0% {
    -webkit-transform: rotate(0deg) translateY(-200%);
    transform: rotate(0deg) translateY(-200%);
  }

  60%,
  100% {
    -webkit-transform: rotate(360deg) translateY(-200%);
    transform: rotate(360deg) translateY(-200%);
  }
}

.__UIV_SCOPE__ .follow-the-leader-line {
  height: 14px;
  position: relative;
  width: 14px;
}

.__UIV_SCOPE__ .follow-the-leader-line div {
  -webkit-animation: follow-the-leader 1.25s infinite backwards;
  animation: follow-the-leader 1.25s infinite backwards;
  background-color: #ffffff;
  border-radius: 100%;
  height: 100%;
  width: 100%;
}

.__UIV_SCOPE__ .follow-the-leader-line div:nth-child(1) {
  -webkit-animation-delay: 0.15s;
  animation-delay: 0.15s;
  background-color: rgba(255, 255, 255, 0.9);
}

.__UIV_SCOPE__ .follow-the-leader-line div:nth-child(2) {
  -webkit-animation-delay: 0.3s;
  animation-delay: 0.3s;
  background-color: rgba(255, 255, 255, 0.8);
}

.__UIV_SCOPE__ .follow-the-leader-line div:nth-child(3) {
  -webkit-animation-delay: 0.45s;
  animation-delay: 0.45s;
  background-color: rgba(255, 255, 255, 0.7);
}

.__UIV_SCOPE__ .follow-the-leader-line div:nth-child(4) {
  -webkit-animation-delay: 0.6s;
  animation-delay: 0.6s;
  background-color: rgba(255, 255, 255, 0.6);
}

.__UIV_SCOPE__ .follow-the-leader-line div:nth-child(5) {
  -webkit-animation-delay: 0.75s;
  animation-delay: 0.75s;
  background-color: rgba(255, 255, 255, 0.5);
}
